def find_middle(s):
    if not isinstance(s, str):
        return -1
    digits = [int(c) for c in s if c.isdigit()]
    if not digits:
        return -1
    product = 1
    for digit in digits:
        product *= digit
    product_str = str(product)
    length = len(product_str)
    if length % 2 == 1:
        return int(product_str[length // 2])
    else:
        mid = product_str[(length // 2) - 1:(length // 2) + 1]
        return int(mid.lstrip('0')) if mid != '00' else 0
